// Builds CREDITS.md from the data, so the credits can never drift from what the site shows.
const cell = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\s+/g, " ").trim();

export function creditsMarkdown(D) {
  const hosted = D.thinkers.filter((k) => k.portrait);
  const out = [
    "# Image credits",
    "",
    "<!-- Generated by `node scripts/fetch-portraits.mjs` from public/data/thinkers.js. Do not edit by hand. -->",
    "",
    `${hosted.length} portraits are hosted with this site, resized from files on Wikimedia Commons. Licences, authors and file`,
    "pages were read from the Commons API. Each file page has the full licence and source details; check it before reusing",
    "an image. Other pictures in the panels are loaded from Wikipedia at view time and credited there.",
    "",
    "| Thinker | Author | Licence | Source |",
    "| --- | --- | --- | --- |"
  ];
  for (const k of hosted) {
    const im = k.portrait;
    const lic = im.licenseUrl ? `[${cell(im.license)}](${im.licenseUrl})` : cell(im.license);
    out.push(`| ${cell(k.name.en)} | ${cell(im.author)} | ${lic} | [Commons](${im.page}) |`);
  }
  return out.join("\n") + "\n";
}
